    "atlas_id": "CA-0002-bfc76f16",
    "id": "CA-0002-bfc76f16",
    "title": "Women's Rights",
    "poet": "Annie Louisa Walker",
    "author": "Annie Louisa Walker",
    "country": "Canada",
    "country_code": "CA",
    "place": "Canada",
    "continent": "Americas",
    "language": "English",
    "original_language": "English",
    "kind": "poem",
