    "id": "IE-0001-2a67537b",
    "title": "CHARMIDES",
    "poet": "Oscar Wilde",
    "author": "Oscar Wilde",
    "country": "Ireland",
    "country_code": "IE",
    "place": "Ireland",
    "continent": "Europe",
