    "title": "This Life Is All Chequer'd With Pleasures and Woes",
    "poet": "Thomas Moore",
    "author": "Thomas Moore",
    "country": "Ireland",
    "country_code": "IE",
    "place": "Ireland",
    "continent": "Europe",
    "language": "English",
    "original_language": "English",
