    "atlas_id": "US-0136-23913df5",
    "id": "US-0136-23913df5",
    "title": "Nature -- the Gentlest Mother is,",
    "poet": "Emily Dickinson",
    "author": "Emily Dickinson",
    "country": "United States of America",
    "country_code": "US",
    "place": "United States of America",
    "continent": "Americas",
    "language": "English",
    "original_language": "English",
    "kind": "poem",
